using System;using System.IO;using System.Reflection;using System.Threading;using System.Threading.Tasks;using UnityEngine;using FlyEditor.Flight;using FlyEditor.Editor;
public static class ClearanceCommonVerification {
 static void Check(bool v,string m){if(!v)throw new Exception("[ClearCommon] "+m);}
 public static string Folder=>Environment.GetEnvironmentVariable("FLYEDITOR_CLEARANCE")??Path.GetFullPath(Path.Combine(Application.dataPath,"../../Docs/OrigamiAudit/petal-clearance"));
 public static PaperSheet Load()=>PaperSheet.Replay(JsonUtility.FromJson<ResearchSave>(File.ReadAllText(Path.Combine(Folder,"before-21.json"))).paperFolds);
 public static FoldStep Request(PaperSheet source){
  for(int i=0;i<source.Faces.Count;i++){var f=source.Faces[i];Vector2 Local(Vector2 m){var v=f.material.inverse.MultiplyPoint3x4(new Vector3(m.x,0,m.y));return new Vector2(v.x,v.z);}var tip=Local(Vector2.one*11);if(!f.Contains(tip))continue;
   return new FoldStep{anchor=i,flap=i+1,cornerPull=true,flexible=true,closeFlat=true,exactSquash=true,regionalPull=true,coupledHinges=true,coordinatedCreases=true,adaptiveCreases=true,compactLayers=true,connectedPetalBacking=true,partialPetalBacking=true,pullTip=tip,pullStop=Local(Vector2.one*5.5f)};
  }throw new Exception("missing material corner");
 }
 public static void Variants(PaperSheet source,FoldStep saved){
  var flags=BindingFlags.Instance|BindingFlags.NonPublic;var ctor=typeof(PaperSheet.Face).GetConstructor(flags|BindingFlags.Public,null,new[]{typeof(Vector2[]),typeof(int),typeof(bool),typeof(Matrix4x4),typeof(Matrix4x4)},null);int poses=0;
  foreach(float degrees in new[]{0f,37f,180f,273f})foreach(bool swap in new[]{false,true}){
   var copy=(PaperSheet)typeof(PaperSheet).GetMethod("PlanningCopy",flags).Invoke(source,null);var transform=Matrix4x4.TRS(new Vector3(2,-1,3),Quaternion.AngleAxis(degrees,new Vector3(1,2,3).normalized),Vector3.one);var faces=new System.Collections.Generic.List<PaperSheet.Face>();
   foreach(var f in source.Faces)faces.Add((PaperSheet.Face)ctor.Invoke(new object[]{f.points,f.layer,f.back,transform*f.frame,f.material}));typeof(PaperSheet).GetField("faces",flags).SetValue(copy,faces);
   var step=saved;if(swap){var temp=step.pullLeft;step.pullLeft=step.pullRight;step.pullRight=temp;}var p=PaperCornerPull.Create(copy,step);if(p==null){var debug=(PaperSheet)typeof(PaperSheet).GetMethod("PlanningCopy",flags).Invoke(copy,null);int index=0;foreach(var prep in step.clearance){var st=(FoldStep)typeof(FoldPreparation).GetProperty("Step",flags).GetValue(prep);var turn=debug.Plan(st);Debug.Log("[ClearVariant] stage="+index+++" allowed="+(turn==null?999:turn.Constrain(st.degrees))+" desired="+st.degrees);if(!debug.ApplyStep(st))break;}var petalType=typeof(PaperSheet).Assembly.GetType("FlyEditor.Flight.PaperFoldClearance");var handles=petalType.GetMethod("Handles",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{copy,step});var args=new object[]{debug,step,handles,step.clearanceDirection,null};Debug.Log("[ClearVariant] resolve="+petalType.GetMethod("Resolve",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args));}Check(p!=null,"rotated sequence "+degrees+"/"+swap);
   for(int a=0;a<=180;a+=15){Check(p.Pose(step.clearanceDirection*a),"rotated pose");ReverseDirectionVerification.Geometry(p.Preview);poses++;}
  }Debug.Log("[ClearCommon] 8 transformed/swapped sequences, "+poses+" poses preserve seams and area");
 }
 [UnityEditor.MenuItem("Tools/FlyEditor/Validation/Petal clearance sequence")]
 public static void Run(){var source=Load();var original=source.Faces;FoldStep request=Request(source);var type=typeof(PaperSheet).Assembly.GetType("FlyEditor.Flight.PaperFoldClearance");var method=type.GetMethod("Search",BindingFlags.Static|BindingFlags.NonPublic);var watch=System.Diagnostics.Stopwatch.StartNew();var task=Task.Run(()=>method.Invoke(null,new object[]{source,request,CancellationToken.None}));var result=task.GetAwaiter().GetResult();Check(result!=null,"no generic route");var field=BindingFlags.Instance|BindingFlags.NonPublic;var saved=(FoldStep)result.GetType().GetField("step",field).GetValue(result);Debug.Log("[ClearCommon] search ms="+watch.ElapsedMilliseconds+" visits="+result.GetType().GetField("visited",field).GetValue(result)+" preparations="+saved.clearance.Length);Check(ReferenceEquals(original,source.Faces),"planning changed source");Variants(source,saved);
 var invalid=saved;invalid.clearance=(FoldPreparation[])saved.clearance.Clone();invalid.clearance[0].degrees*=-1;Check(PaperCornerPull.Create(source,invalid)==null,"blocked preparation direction accepted");invalid.clearance[0].anchor=-1;Check(PaperCornerPull.Create(source,invalid)==null,"invalid preparation anchor");invalid=saved;invalid.clearanceDirection=0;Check(PaperCornerPull.Create(source,invalid)==null,"invalid sequence direction");
 using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();Check(method.Invoke(null,new object[]{source,request,cancelled.Token})==null,"cancelled search returned a path");}
 var p=PaperCornerPull.Create(source,saved);Check(p!=null&&p.UsesClearanceSequence,"sequence create");int sign=saved.clearanceDirection;for(int a=0;a<=180;a+=2){Check(p.Pose(sign*a),"pose "+a);ReverseDirectionVerification.Geometry(p.Preview);}foreach(float a in new[]{179.9f,15,0,80,179.99f,30,180}){Check(p.Pose(sign*a),"scrub "+a);ReverseDirectionVerification.Geometry(p.Preview);}Check(!p.Pose(-sign*5),"opposite direction bypass");Check(!p.Pose(float.NaN)&&!p.Pose(181),"invalid angles");foreach(float a in new[]{30f,90f,150f,180f}){Check(source.FinishPull(p,sign*a),"commit "+a);PetalFoldingVerification.Replay(source);ReverseDirectionVerification.Geometry(source.Faces);Check(source.Undo()&&ReferenceEquals(original,source.Faces),"undo "+a);p=PaperCornerPull.Create(source,saved);}var originalTip=source.Faces[saved.anchor].material.MultiplyPoint3x4(new Vector3(saved.pullTip.x,0,saved.pullTip.y));var start=source.Faces[saved.anchor].World(saved.pullTip,0);
 Check(source.FinishPull(p,sign*180),"final");bool displaced=false;foreach(var f in source.Faces){var local=f.material.inverse.MultiplyPoint3x4(originalTip);var point=new Vector2(local.x,local.z);if(f.Contains(point))displaced|=Vector3.Distance(start,f.World(point,0))>1;}Check(displaced,"target petal did not move");var root=Folder;File.WriteAllText(Path.Combine(root,"common-continued.json"),JsonUtility.ToJson(new ResearchSave{paperFolds=source.Recipe()},true));Debug.Log("[ClearCommon] PASS next petal, continuous sweep, backward scrub, replay, undo, opposite block. folds="+source.Count);}
}
